(function(){
  'use strict';
  var store=window.TradeJournalSessionSignatureStore,engine=window.TradeJournalSessionSignatureEngine,i18n=window.TradeJournalSessionSignatureI18n,notified=Object.create(null),THRESHOLD_KEY='tradejournal:session-similarity-threshold:v1';
  if(!store||!engine||!i18n)return;
  function el(tag,className,text){var node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
  function threshold(){var raw=localStorage.getItem(THRESHOLD_KEY);if(raw===null||raw==='')return 70;var value=Number(raw);return value>=0&&value<=100?value:70;}
  function toast(match){var key=match.sessionId;if(notified[key])return;notified[key]=true;var box=el('div','ss-toast',i18n.t('notice',{market:match.market||'—',date:match.date||'—'}));box.setAttribute('role','status');document.body.append(box);requestAnimationFrame(function(){box.classList.add('show');});setTimeout(function(){box.classList.remove('show');setTimeout(function(){box.remove();},220);},4200);}
  async function mount(page,session,character){if(!page||!session)return;var previous=page.querySelector('[data-session-similarity]');if(previous)previous.remove();var section=el('section','ss-panel');section.dataset.sessionSimilarity='';section.dir=i18n.direction();var head=el('header'),title=el('h3','',i18n.t('title')),settings=el('label','ss-threshold'),input=document.createElement('input');input.type='number';input.min='0';input.max='100';input.value=String(threshold());settings.append(el('span','',i18n.t('threshold')),input,document.createTextNode('%'));head.append(title,settings);section.append(head,el('div','ss-loading','…'));var dashboard=page.querySelector('.sw-dashboard');if(dashboard)dashboard.insertAdjacentElement('afterend',section);else page.append(section);input.onchange=function(){var value=Math.max(0,Math.min(100,Number(input.value)||70));localStorage.setItem(THRESHOLD_KEY,String(value));mount(page,session,character);};var live=store.buildPartialFromSession(session,character),matches=await engine.compareWithProvider(live,store.listSync());if(!document.body.contains(section))return;section.querySelector('.ss-loading').remove();var values=matches.slice(0,3);if(!values.length){section.append(el('p','ss-empty',i18n.t('empty')));return;}values.forEach(function(match){var card=el('article','ss-match'),top=el('div'),name=el('strong','',(match.market||'—')+' · '+(match.date||'—')),score=el('b','',match.similarity+'%');top.append(name,score);var meter=el('span','ss-meter'),fill=el('i');fill.style.width=match.similarity+'%';meter.append(fill);var details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=i18n.t('summary');details.append(summary,el('p','',match.fateSummaryText||i18n.t('empty')),el('small','',i18n.t('source')+': '+match.character));card.append(top,meter,details);section.append(card);if(match.similarity>=threshold())toast(match);});if(window.TradeJournalIcons)window.TradeJournalIcons.schedule(section);}
  window.TradeJournalSessionSimilarityUI={mount:mount,threshold:threshold};
}());
